import type { CapacitorConfig } from '@capacitor/cli';

const config: CapacitorConfig = {
  appId: 'com.example.httpdemo',
  appName: 'HttpDemo',
  webDir: 'dist',
  plugins: {
    CapacitorHttp: {
      enabled: true,
    },
  },
};

export default config;

/**
 * Shared domain types used by the typed API client and the round-trip runner.
 */

export interface Product {
  id: number;
  name: string;
  price: number;
}

export interface CreateOrderRequest {
  productId: number;
  quantity: number;
}

export interface Order {
  orderId: string;
  productId: number;
  quantity: number;
  total: number;
}

/**
 * A typed error raised by the API client whenever the HTTP response has a
 * non-2xx status code. The numeric HTTP status is programmatically accessible
 * via the `status` property.
 */
export class ApiRequestError extends Error {
  /** The HTTP status code returned by the server. */
  readonly status: number;
  /** The parsed response body (when available). */
  readonly data: unknown;

  constructor(status: number, data: unknown, message?: string) {
    super(message ?? `API request failed with status ${status}`);
    this.name = 'ApiRequestError';
    this.status = status;
    this.data = data;
  }
}

import { CapacitorHttp, type HttpOptions, type HttpHeaders } from '@capacitor/core';
import { ApiRequestError, type CreateOrderRequest, type Order, type Product } from './types';

/**
 * A strongly-typed API client built on top of `CapacitorHttp`.
 *
 * `CapacitorHttp` resolves with the numeric `status` and parsed `data` for
 * every response — including non-2xx — so this client is responsible for
 * detecting non-2xx statuses and raising a typed {@link ApiRequestError} whose
 * HTTP status is programmatically accessible.
 */
export class ApiClient {
  private readonly baseUrl: string;
  private readonly defaultHeaders: HttpHeaders;

  constructor(baseUrl: string, defaultHeaders: HttpHeaders = {}) {
    this.baseUrl = baseUrl.replace(/\/$/, '');
    this.defaultHeaders = defaultHeaders;
  }

  /** List every product. */
  async listProducts(): Promise<Product[]> {
    return this.request<Product[]>({
      method: 'GET',
      url: `${this.baseUrl}/api/products`,
    });
  }

  /** Fetch a single product by id. */
  async getProduct(id: number): Promise<Product> {
    return this.request<Product>({
      method: 'GET',
      url: `${this.baseUrl}/api/products/${id}`,
    });
  }

  /**
   * Create an order.
   *
   * @param body   The order payload (`productId` and `quantity`).
   * @param apiKey The value to send in the `X-Api-Key` header.
   */
  async createOrder(body: CreateOrderRequest, apiKey: string): Promise<Order> {
    return this.request<Order>({
      method: 'POST',
      url: `${this.baseUrl}/api/orders`,
      headers: {
        'Content-Type': 'application/json',
        'X-Api-Key': apiKey,
      },
      data: body,
    });
  }

  /**
   * Core request helper. Performs the HTTP call through `CapacitorHttp`,
   * merges default headers, and converts non-2xx responses into a typed
   * {@link ApiRequestError}.
   */
  private async request<T>(options: HttpOptions): Promise<T> {
    const mergedHeaders: HttpHeaders = {
      ...this.defaultHeaders,
      ...(options.headers ?? {}),
    };

    const response = await CapacitorHttp.request({
      ...options,
      headers: mergedHeaders,
    });

    if (response.status < 200 || response.status >= 300) {
      const message =
        typeof response.data === 'object' &&
        response.data !== null &&
        'error' in response.data &&
        typeof (response.data as { error: unknown }).error === 'string'
          ? (response.data as { error: string }).error
          : `Request to ${options.url} failed with status ${response.status}`;
      throw new ApiRequestError(response.status, response.data, message);
    }

    return response.data as T;
  }
}

export { ApiRequestError };

import http from 'node:http';
import crypto from 'node:crypto';
import type { Product } from './types';

/**
 * A tiny in-process mock HTTP API server implemented with Node's built-in
 * `http` module. Listens on `http://localhost:8787` (reachable via both
 * `127.0.0.1` and `localhost`) and exposes product/order endpoints.
 */

const PORT = 8787;
const API_KEY = 'local-dev-key-123';

const products: Product[] = [
  { id: 1, name: 'Notebook', price: 5 },
  { id: 2, name: 'Pen', price: 2 },
  { id: 3, name: 'Backpack', price: 40 },
];

function sendJson(
  res: http.ServerResponse,
  status: number,
  body: unknown,
): void {
  const payload = Buffer.from(JSON.stringify(body));
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Content-Length': payload.length,
  });
  res.end(payload);
}

function readBody(req: http.IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url ?? '/', `http://localhost:${PORT}`);
    const pathname = url.pathname;

    // GET /api/products
    if (req.method === 'GET' && pathname === '/api/products') {
      sendJson(res, 200, products);
      return;
    }

    // GET /api/products/:id
    const productMatch = pathname.match(/^\/api\/products\/(\d+)$/);
    if (req.method === 'GET' && productMatch) {
      const id = Number(productMatch[1]);
      const product = products.find((p) => p.id === id);
      if (!product) {
        sendJson(res, 404, { error: `Product with id ${id} not found` });
        return;
      }
      sendJson(res, 200, product);
      return;
    }

    // POST /api/orders
    if (req.method === 'POST' && pathname === '/api/orders') {
      const apiKey = req.headers['x-api-key'];
      if (apiKey !== API_KEY) {
        sendJson(res, 401, { error: 'Invalid or missing API key' });
        return;
      }

      const raw = await readBody(req);
      let parsed: { productId?: unknown; quantity?: unknown };
      try {
        parsed = JSON.parse(raw);
      } catch {
        sendJson(res, 400, { error: 'Invalid JSON body' });
        return;
      }

      const productId = Number(parsed.productId);
      const quantity = Number(parsed.quantity);

      const product = products.find((p) => p.id === productId);
      if (!product) {
        sendJson(res, 404, { error: `Product with id ${productId} not found` });
        return;
      }

      if (!Number.isInteger(quantity) || quantity < 1) {
        sendJson(res, 400, { error: 'Quantity must be a positive integer' });
        return;
      }

      const orderId = crypto.randomUUID();
      const total = product.price * quantity;
      sendJson(res, 201, {
        orderId,
        productId: product.id,
        quantity,
        total,
      });
      return;
    }

    // Fallback
    sendJson(res, 404, { error: `Route ${req.method} ${pathname} not found` });
  } catch (err) {
    sendJson(res, 500, { error: 'Internal server error' });
  }
});

server.listen(PORT, () => {
  console.log(`Mock API server listening on http://localhost:${PORT}`);
});

export { server };

import { ApiClient } from './api-client';
import { ApiRequestError } from './types';

/**
 * Round-trip CLI runner.
 *
 * Assumes the mock server is already running on http://localhost:8787.
 * Drives the typed client through the required scenario and prints a single
 * machine-readable summary line starting with `RESULT: `.
 */

const BASE_URL = 'http://localhost:8787';
const API_KEY = 'local-dev-key-123';

async function main(): Promise<void> {
  const client = new ApiClient(BASE_URL);

  // 1. List all products.
  const products = await client.listProducts();
  const productCount = products.length;

  // 2. Fetch the product with id 2.
  const product2 = await client.getProduct(2);
  const product2Name = product2.name;

  // 3. Create an order for productId 3, quantity 2, using the correct API key.
  const order = await client.createOrder(
    { productId: 3, quantity: 2 },
    API_KEY,
  );
  const orderId = order.orderId;
  const orderTotal = order.total;

  // 4. Attempt to fetch product 999 and capture the HTTP status from the error.
  let missingProductStatus = 0;
  try {
    await client.getProduct(999);
  } catch (err) {
    if (err instanceof ApiRequestError) {
      missingProductStatus = err.status;
    } else {
      throw err;
    }
  }

  // 5. Attempt to create an order with an incorrect API key and capture the
  //    HTTP status from the error.
  let unauthorizedStatus = 0;
  try {
    await client.createOrder(
      { productId: 3, quantity: 2 },
      'wrong-key',
    );
  } catch (err) {
    if (err instanceof ApiRequestError) {
      unauthorizedStatus = err.status;
    } else {
      throw err;
    }
  }

  const summary = {
    productCount,
    product2Name,
    orderId,
    orderTotal,
    missingProductStatus,
    unauthorizedStatus,
  };

  console.log(`RESULT: ${JSON.stringify(summary)}`);
  process.exit(0);
}

main().catch((err) => {
  console.error('Round-trip failed:', err);
  process.exit(1);
});

